import React, { useState, useEffect, useCallback } from 'react';
import { 
  Calculator, 
  RefreshCw, 
  FileText, 
  Layers, 
  Users, 
  Wrench, 
  Package, 
  Truck, 
  ChevronRight, 
  AlertCircle,
  CheckCircle2,
  Info
} from 'lucide-react';
import axios from '../../api/axiosConfig';
import { motion, AnimatePresence } from 'framer-motion';

const MotionDiv = motion.div;

const FormulaPolinomicaTab = ({ projectId, activeRevision }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [formulaData, setFormulaData] = useState(null);
  const [calculating, setCalculating] = useState(false);
  const [presupuestoId, setPresupuestoId] = useState(null);
  const [resources, setResources] = useState([]);
  const [activeCategory, setActiveCategory] = useState('EQUIPOS');
  const [activeTab, setActiveTab] = useState('INDICES'); // INDICES | CUADRILLA

  const categories = [
    { id: 'EQUIPOS', name: 'Equipos y Herramientas', icon: Wrench, sc: 1 },
    { id: 'MATERIALES', name: 'Materiales', icon: Package, sc: 2 },
    { id: 'TRANSPORTE', name: 'Transporte', icon: Truck, sc: 3 },
    { id: 'MANO_OBRA', name: 'Mano de Obra', icon: Users, sc: 4 },
  ];

  const fetchResources = async (pId) => {
    try {
      setLoading(true);
      const resp = await axios.get(`/polinomica/${pId}/resources`);
      setResources(resp.data);
    } catch (error) {
      console.error("Error fetching resources:", error);
      setError("Error al cargar recursos del presupuesto");
    } finally {
      setLoading(false);
    }
  };

  const saveAssignment = async (recursoId, simbolo) => {
    try {
      setCalculating(true);
      await axios.post(`/polinomica/${presupuestoId}/assignments`, [
        { recurso_id: recursoId, simbolo }
      ]);
      // Regenerar automáticamente tras asignar
      await generateFormula();
      await fetchResources(presupuestoId);
    } catch (_error) {
      setError("Error al guardar la asignación");
    } finally {
      setCalculating(false);
    }
  };

  const resolvePresupuesto = useCallback(async () => {
    if (!projectId) {
      console.warn("[PolinomicaTab] No projectId provided");
      return;
    }
    setLoading(true);
    try {
      console.log(`[PolinomicaTab] Fetching budgets for project ${projectId}...`);
      const response = await axios.get('/presupuestos/', { 
        params: { proyecto_id: projectId } 
      });
      const budgets = response.data;
      console.log(`[PolinomicaTab] Found ${budgets.length} budgets`, budgets);

      const currentPres = budgets.find(p => p.revision === activeRevision?.revision) || budgets[0];
      if (currentPres) {
        console.log(`[PolinomicaTab] Selecting budget ID: ${currentPres.id}`);
        setPresupuestoId(currentPres.id);
      } else {
        console.error("[PolinomicaTab] No budget found in list");
        setError("No se encontró un presupuesto activo para este proyecto");
      }
    } catch (error) {
      console.error("[PolinomicaTab] Error resolving presupuesto:", error);
      setError('Error al cargar presupuestos');
    } finally {
      setLoading(false);
    }
  }, [projectId, activeRevision?.revision]);

  const [selectedType, setSelectedType] = useState('SIN_DESGLOSE');

  const loadData = async (id) => {
    if (!id) return;
    setLoading(true);
    setError(null);
    try {
      console.log(`[PolinomicaTab] Loading data for presupuesto ${id}...`);
      const [formulaResp, resourcesResp] = await Promise.allSettled([
        axios.get(`/polinomica/${id}`),
        axios.get(`/polinomica/${id}/resources`)
      ]);

      if (formulaResp.status === 'fulfilled') {
        setFormulaData(formulaResp.value.data);
        if (formulaResp.value.data.tipo) setSelectedType(formulaResp.value.data.tipo);
      } else {
        console.warn("[PolinomicaTab] Formula not found or error:", formulaResp.reason);
        setFormulaData(null);
      }

      if (resourcesResp.status === 'fulfilled') {
        console.log(`[PolinomicaTab] Resources loaded: ${resourcesResp.value.data.length} items`);
        setResources(resourcesResp.value.data);
      } else {
        console.error("[PolinomicaTab] Failed to load resources:", resourcesResp.reason);
        setError("Error al cargar recursos del presupuesto");
      }
    } catch (error) {
      console.error("Error in loadData:", error);
      setError("Error crítico al cargar datos");
    } finally {
      setLoading(false);
    }
  };

  const generateFormula = async (typeToUse) => {
    if (!presupuestoId) return;
    const finalType = typeToUse || selectedType;
    setCalculating(true);
    try {
      const response = await axios.post(`/polinomica/${presupuestoId}/regenerate`, null, {
        params: { tipo: finalType }
      });
      setFormulaData(response.data);
      setSelectedType(finalType); // Sincronizar estado local con el modo generado
    } catch (_error) {
      setError('Error al generar la fórmula');
    } finally {
      setCalculating(false);
    }
  };

  useEffect(() => { resolvePresupuesto(); }, [resolvePresupuesto]);
  useEffect(() => { 
    if (presupuestoId) {
      loadData(presupuestoId);
    }
  }, [presupuestoId]);

  const filteredResources = resources.filter(r => {
    const cat = categories.find(c => c.id === activeCategory);
    if (!cat) return false;

    const scCode = r.subcategoria_codigo !== null && r.subcategoria_codigo !== undefined 
      ? Number(r.subcategoria_codigo) 
      : null;

    // Fallback: Si es Materiales (2), mostrar también los que no tienen código o tienen código 5 (APUs/Otros)
    if (cat.sc === 2) {
      return scCode === 2 || scCode === 5 || scCode === null || scCode === undefined;
    }

    return scCode === cat.sc;
  });

  const getCountBySc = (sc) => {
    if (sc === 2) {
      return resources.filter(r => {
        const c = r.subcategoria_codigo;
        return c === 2 || c === 5 || c === null || c === undefined;
      }).length;
    }
    return resources.filter(r => Number(r.subcategoria_codigo) === sc).length;
  };

  const terminos = ["B", "C", "D", "E", "M", "P", "R", "X"];

  const assignSuggested = async () => {
    try {
      setCalculating(true);
      const toAssign = filteredResources
        .filter(r => !r.termino_actual)
        .map(r => ({ recurso_id: r.recurso_id, simbolo: r.termino_sugerido }));

      if (toAssign.length === 0) return;

      await axios.post(`/polinomica/${presupuestoId}/assignments`, toAssign);
      await generateFormula();
      await fetchResources(presupuestoId);
    } catch (_error) {
      setError("Error al aplicar sugerencias");
    } finally {
      setCalculating(false);
    }
  };

  const resourcesToAssign = resources.filter(r => !r.termino_actual).length;

  if (loading && !formulaData) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <RefreshCw className="w-10 h-10 text-[#F39200] animate-spin mb-4" />
        <p className="text-zinc-500 font-bold uppercase tracking-widest text-[10px]">Cargando módulo de polínomica...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full space-y-6 animate-in fade-in duration-500">

      {error && (
        <div className="mx-2 p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-center gap-3 text-rose-600 animate-in slide-in-from-top-2">
          <AlertCircle className="w-4 h-4" />
          <p className="text-xs font-bold">{error}</p>
          <button onClick={() => setError(null)} className="ml-auto text-rose-400 hover:text-rose-600">
            <RefreshCw className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* --- NEW PREMIUM HEADER BAR (Style Image 2) --- */}
      <div className="bg-white rounded-[2rem] shadow-sm border border-zinc-100 p-4 flex items-center justify-between">
        <div className="flex items-center gap-6 pl-2">
          <div className="w-12 h-12 rounded-2xl bg-rose-50 flex items-center justify-center shadow-inner">
            <Calculator className="w-6 h-6 text-rose-500" />
          </div>
          <div>
            <div className="flex items-center gap-3 mb-1">
              <p className="text-[10px] font-black text-rose-500 uppercase tracking-[0.2em]">Fórmula Polinómica</p>
              <span className="px-2 py-0.5 bg-zinc-100 rounded-full text-[8px] font-black text-zinc-400 uppercase tracking-widest border border-zinc-200">
                Modo: {selectedType === 'CON_DESGLOSE' ? 'Desglose Equipos' : 'Estándar'}
              </span>
            </div>
            <h2 className="text-lg font-black uppercase tracking-tight text-[#1A1A1A]">
              Monomios {presupuestoId && `(#${presupuestoId})`}
            </h2>
            <div className="flex items-center gap-4">
              <p className="text-[10px] text-zinc-400 font-medium">
                {resources.length} recursos totales detectados
              </p>
              <button 
                onClick={() => { resolvePresupuesto(); if(presupuestoId) loadData(presupuestoId); }}
                className="text-[9px] font-black text-rose-500 hover:text-rose-600 underline uppercase tracking-widest flex items-center gap-1"
                title="Forzar recarga de presupuesto y recursos"
              >
                <RefreshCw className="w-2.5 h-2.5" />
                Forzar Sincronización
              </button>
            </div>
          </div>
        </div>

        {/* Mode Switcher Pill */}
        <div className="flex bg-zinc-100 p-1 rounded-2xl border border-zinc-100 shadow-inner scale-90 xxl:scale-100">
          <button 
            onClick={() => generateFormula('SIN_DESGLOSE')}
            disabled={calculating}
            className={`px-6 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${selectedType === 'SIN_DESGLOSE' ? 'bg-white text-[#F39200] shadow-md border border-zinc-200' : 'text-zinc-400 hover:text-zinc-600'}`}
          >
            ESTÁNDAR
          </button>
          <button 
            onClick={() => generateFormula('CON_DESGLOSE')}
            disabled={calculating}
            className={`px-6 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${selectedType === 'CON_DESGLOSE' ? 'bg-white text-[#F39200] shadow-md border border-zinc-200' : 'text-zinc-400 hover:text-zinc-600'}`}
          >
            CON DESGLOSE
          </button>
        </div>

        <div className="flex items-center gap-4">
          {/* Metrics Pills */}
          <div className="flex items-center gap-1 bg-zinc-50 p-1.5 rounded-2xl border border-zinc-100">
            <div className="px-4 py-2 bg-white rounded-xl shadow-sm border border-orange-100">
              <p className="text-[8px] font-black text-zinc-400 uppercase tracking-widest leading-none mb-1">Pendientes</p>
              <div className="flex items-center gap-2">
                <span className={`text-sm font-black ${resourcesToAssign > 0 ? 'text-orange-600' : 'text-emerald-600'}`}>
                  {resourcesToAssign} <span className="text-[9px] text-zinc-400">/ {resources.length} total</span>
                </span>
              </div>
            </div>

            <div className="px-4 py-2 bg-white rounded-xl shadow-sm border border-blue-50">
              <p className="text-[8px] font-black text-zinc-400 uppercase tracking-widest leading-none mb-1">Suma Coef.</p>
              <p className="text-sm font-black text-[#136191] italic">1.000</p>
            </div>

            <div className="px-4 py-2 bg-white rounded-xl shadow-sm border border-zinc-100">
              <p className="text-[8px] font-black text-zinc-400 uppercase tracking-widest leading-none mb-1">P.O. Base</p>
              <p className="text-sm font-black text-zinc-900 tabular-nums">
                ${parseFloat(formulaData?.costo_directo_total || 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
              </p>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex items-center gap-2 ml-2">
            <button 
              onClick={assignSuggested}
              disabled={calculating || resourcesToAssign === 0}
              className={`flex items-center gap-2 px-6 py-3 bg-[#F39200] hover:bg-[#D98300] text-white rounded-xl text-[10px] font-black tracking-widest transition-all shadow-lg active:scale-95 disabled:opacity-50 disabled:grayscale`}
            >
              <CheckCircle2 className="w-3.5 h-3.5" />
              ASIGNAR SUGERIDOS
            </button>
            <button 
              onClick={() => generateFormula()}
              className="p-3 bg-white rounded-xl border border-zinc-200 shadow-sm hover:bg-zinc-50 transition-all active:scale-95 group"
              title="Refrescar Cálculos"
            >
              <RefreshCw className={`w-4 h-4 text-zinc-400 group-hover:text-[#F39200] ${calculating ? 'animate-spin' : ''}`} />
            </button>
            <button className="p-3 bg-white rounded-xl border border-zinc-200 shadow-sm hover:bg-zinc-50 transition-all active:scale-95 group">
              <FileText className="w-4 h-4 text-zinc-400 group-hover:text-emerald-500" />
            </button>
          </div>
        </div>
      </div>

      {/* Upper Area: Assignment Layout */}
      <div className="grid grid-cols-12 gap-4 h-[400px]">
        {/* Left Sidebar: Categories */}
        <div className="col-span-3 bg-white rounded-xl shadow-sm border border-gray-100 p-2 space-y-1">
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-3 py-2">Listado de Categorías</p>
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-lg transition-all ${activeCategory === cat.id ? 'bg-orange-500 text-white shadow-lg' : 'text-gray-600 hover:bg-gray-50'}`}
            >
              <div className="flex items-center gap-3">
                <cat.icon className="w-4 h-4" />
                <span className="text-xs font-bold">{cat.name}</span>
              </div>
              <span className={`text-[10px] font-black ${activeCategory === cat.id ? 'text-orange-100' : 'text-zinc-400'}`}>
                {getCountBySc(cat.sc)}
              </span>
            </button>
          ))}
        </div>

        {/* Center/Right: Resource Table */}
        <div className="col-span-9 bg-white rounded-xl shadow-sm border border-gray-100 flex flex-col overflow-hidden">
          <div className="overflow-auto flex-1">
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-gray-50 border-b border-gray-100 z-10">
                <tr className="text-[10px] text-gray-400 uppercase font-black tracking-widest leading-none">
                  <th className="px-4 py-3">#</th>
                  <th className="px-4 py-3">Término</th>
                  <th className="px-4 py-3">Código</th>
                  <th className="px-4 py-3">Descripción</th>
                  <th className="px-4 py-3">Unidad</th>
                  <th className="px-4 py-3 text-right">C. Directo</th>
                  <th className="px-4 py-3">Asignación</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {resources.length === 0 && loading ? (
                  <tr>
                    <td colSpan="7" className="px-4 py-8 text-center text-gray-400">
                      <RefreshCw className="w-4 h-4 animate-spin inline mr-2" />
                      Cargando recursos del presupuesto...
                    </td>
                  </tr>
                ) : filteredResources.length === 0 ? (
                  <tr>
                    <td colSpan="7" className="px-4 py-8 text-center text-gray-400 font-medium italic">
                      No se encontraron recursos del presupuesto en esta categoría.
                    </td>
                  </tr>
                ) : (
                  filteredResources.map((res, idx) => (
                    <tr key={res.recurso_id} className="hover:bg-blue-50/50 group text-xs text-gray-700">
                      <td className="px-4 py-2 text-[10px] text-gray-400 font-mono">{String(idx+1).padStart(4, '0')}</td>
                      <td className="px-4 py-2 font-black text-orange-600 text-sm italic">{res.termino_actual || '-'}</td>
                      <td className="px-4 py-2 text-[10px] font-medium text-gray-500">{res.codigo}</td>
                      <td className="px-4 py-2 truncate max-w-[200px]" title={res.descripcion}>{res.descripcion}</td>
                      <td className="px-4 py-2 text-gray-400">{res.unidad}</td>
                      <td className="px-4 py-2 text-right font-mono">${res.costo_total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                      <td className="px-4 py-2">
                        <select 
                          value={res.termino_actual || ''}
                          onChange={(e) => saveAssignment(res.recurso_id, e.target.value)}
                          className="bg-transparent border-0 font-bold text-blue-600 focus:ring-0 p-0 text-[10px] cursor-pointer hover:underline"
                        >
                          <option value="">(Sin asignar)</option>
                          {terminos.map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>


      {/* Lower Area: Detailed Tabs */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 flex-1 flex flex-col min-h-[300px] overflow-hidden">
        <div className="flex border-b border-gray-100 bg-gray-50/50">
          <button 
            onClick={() => setActiveTab('INDICES')}
            className={`px-6 py-3 text-[10px] font-black tracking-widest uppercase transition-all ${activeTab === 'INDICES' ? 'bg-white border-r border-gray-100 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Índices y Coeficientes
          </button>
          <button 
            onClick={() => setActiveTab('CUADRILLA')}
            className={`px-6 py-3 text-[10px] font-black tracking-widest uppercase transition-all ${activeTab === 'CUADRILLA' ? 'bg-white border-l border-r border-gray-100 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Cuadrilla Tipo
          </button>
        </div>

        <div className="overflow-auto flex-1">
          {activeTab === 'INDICES' ? (
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-white border-b border-gray-50 z-10 shadow-sm">
                <tr className="text-[10px] text-gray-400 uppercase font-black tracking-widest">
                  <th className="px-6 py-4">#</th>
                  <th className="px-6 py-4">Término</th>
                  <th className="px-6 py-4">Código</th>
                  <th className="px-6 py-4">Descripción de Índice</th>
                  <th className="px-6 py-4 text-right">C. Directo</th>
                  <th className="px-6 py-4 text-right">Coeficiente</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {/* Término Fijo A */}
                <tr className="bg-blue-50/20 font-medium">
                  <td className="px-6 py-3 text-[10px] font-mono text-gray-400">0000</td>
                  <td className="px-6 py-3 font-black text-blue-600 text-base italic">A</td>
                  <td className="px-6 py-3 text-[10px] text-gray-500">000</td>
                  <td className="px-6 py-3 text-xs">Gastos Generales y Utilidad (Término Fijo No Reajustable)</td>
                  <td className="px-6 py-3 text-right font-mono text-xs">---</td>
                  <td className="px-6 py-3 text-right font-mono text-base font-black text-gray-900">{parseFloat(formulaData?.coeficiente_fijo || 0).toFixed(3)}</td>
                </tr>
                {formulaData?.monomios?.map((m, i) => (
                  <tr key={m.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-2 text-[10px] font-mono text-gray-400">{String(i+1).padStart(4, '0')}</td>
                    <td className="px-6 py-2 font-black text-orange-600 text-base italic">{m.simbolo}</td>
                    <td className="px-6 py-2 text-[10px] text-gray-500">{m.indice_inec_id || '---'}</td>
                    <td className="px-6 py-2 text-xs truncate max-w-xs">{m.descripcion}</td>
                    <td className="px-6 py-2 text-right font-mono text-xs">${(parseFloat(m.coeficiente) * parseFloat(formulaData.costo_directo_total)).toLocaleString(undefined, {minimumFractionDigits: 2})}</td>
                    <td className="px-6 py-2 text-right font-mono text-base font-black text-gray-900">{m.coeficiente}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <table className="w-full text-left border-collapse">
              <thead className="sticky top-0 bg-white border-b border-gray-50 z-10 shadow-sm">
                <tr className="text-[10px] text-gray-400 uppercase font-black tracking-widest">
                  <th className="px-6 py-4">#</th>
                  <th className="px-6 py-4">Descripción de Recurso</th>
                  <th className="px-6 py-4 text-right">Coeficiente</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {formulaData?.cuadrilla_tipo?.map((item, idx) => (
                  <tr key={item.id} className="hover:bg-blue-50/50 transition-colors text-xs">
                    <td className="px-6 py-3 text-[10px] font-mono text-gray-400">{String(idx+1).padStart(4, '0')}</td>
                    <td className="px-6 py-3 font-medium text-gray-800">{item.recurso_descripcion}</td>
                    <td className="px-6 py-3 text-right font-mono font-black text-blue-700">{(parseFloat(item.coeficiente_incidencia || 0) * 100).toFixed(2)}%</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Footer Text */}
      <div className="bg-gray-50 p-4 rounded-xl text-center border border-gray-100">
        <p className="text-[10px] font-serif italic text-gray-600">
          Fórmula Polinómica General: <span className="font-bold text-blue-700">PR = P0 [ {parseFloat(formulaData?.coeficiente_fijo || 0).toFixed(3)} A + {formulaData?.monomios?.map(m => `${m.coeficiente}(${m.simbolo}1/${m.simbolo}0)`).join(' + ')} ]</span>
        </p>
      </div>
    </div>
  );
};

export default FormulaPolinomicaTab;

import React, { useState } from 'react';
import { Plus, Trash2 } from 'lucide-react';
import { Input } from '../ui/input';
import { LiquidButton } from '../ui/liquid-button';
import { rolesApi } from '../../api/stakeholders';
import { appAlert, appConfirm } from '../../utils/appDialog';
import { AppModalShell, AppModalHeader, AppModalBody } from '../ui/app-modal';

// eslint-disable-next-line react-refresh/only-export-components
const RolesModal = ({ isOpen, onClose, roles, onUpdate, empresaId = null }) => {
    const [newRol, setNewRol] = useState({ nombre: '', descripcion: '' });
    const [isSaving, setIsSaving] = useState(false);

    const handleCreate = async () => {
        if (!newRol.nombre) return;
        try {
            setIsSaving(true);
            await rolesApi.create(newRol, empresaId);
            setNewRol({ nombre: '', descripcion: '' });
            onUpdate();
        } catch (error) {
            console.error("Error creating rol:", error);
        } finally {
            setIsSaving(false);
        }
    };

    const handleDelete = async (id) => {
        const confirmed = await appConfirm({
            title: 'Eliminar rol',
            message: '¿Eliminar este rol? Asegúrese de que no esté asignado.',
            confirmLabel: 'Eliminar',
            cancelLabel: 'Cancelar',
            tone: 'danger'
        });
        if (!confirmed) return;
        try {
            await rolesApi.delete(id, empresaId);
            onUpdate();
        } catch (_error) {
            appAlert("No se pudo eliminar el rol. Probablemente esté en uso.");
        }
    };

    if (!isOpen) return null;

    return (
        <AppModalShell size="lg" zIndex="z-[110]">
            <AppModalHeader
                title="Gestionar Roles / Funciones"
                subtitle="Catálogo operativo de roles y funciones del proyecto."
                onClose={onClose}
            />
            <AppModalBody className="space-y-6">
                <div className="space-y-4">
                    <div className="flex gap-3">
                        <Input
                            placeholder="Nombre del Rol (ej: Fiscalizador)"
                            value={newRol.nombre}
                            onChange={e => setNewRol({ ...newRol, nombre: e.target.value })}
                            className="flex-1 rounded-xl h-11"
                        />
                        <LiquidButton onClick={handleCreate} disabled={isSaving} className="!h-11 !px-6 bg-purple-600 text-white rounded-xl">
                            <Plus className="w-4 h-4 mr-2" /> Añadir
                        </LiquidButton>
                    </div>
                    <Input
                        placeholder="Descripción breve de la función..."
                        value={newRol.descripcion}
                        onChange={e => setNewRol({ ...newRol, descripcion: e.target.value })}
                        className="rounded-xl h-11"
                    />
                </div>

                <div className="max-h-60 overflow-y-auto custom-scrollbar space-y-2">
                    {roles.length === 0 ? (
                        <p className="text-center py-4 text-zinc-400 text-xs font-bold uppercase tracking-widest italic">No hay roles definidos</p>
                    ) : roles.map(rol => (
                        <div key={rol.id} className="flex items-center justify-between p-4 bg-zinc-50 rounded-2xl group">
                            <div>
                                <p className="text-[10px] font-black text-purple-600 tracking-widest">{rol.codigo}</p>
                                <p className="font-bold text-sm uppercase">{rol.nombre}</p>
                            </div>
                            <button onClick={() => handleDelete(rol.id)} className="p-2 text-zinc-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all">
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    ))}
                </div>
            </AppModalBody>
        </AppModalShell>
    );
};

