import { createContext, useContext, useEffect, useMemo, useRef, useState, useCallback } from 'react';
import { AnimatePresence } from 'framer-motion';
import { AlertTriangle, CheckCircle2, Info, MessageSquareQuote, PencilLine, X } from 'lucide-react';
import { LiquidButton } from './liquid-button';
import { appAlert, appConfirm, appPrompt, registerAppDialogHandler, unregisterAppDialogHandler } from '../../utils/appDialog';

const AppDialogContext = createContext({
    alert: appAlert,
    confirm: appConfirm,
    prompt: appPrompt,
});

const DEFAULTS = {
    alert: {
        title: 'Aviso del sistema',
        confirmLabel: 'Aceptar',
        tone: 'info',
    },
    confirm: {
        title: 'Confirmación',
        confirmLabel: 'Confirmar',
        cancelLabel: 'Cancelar',
        tone: 'warning',
    },
    prompt: {
        title: 'Entrada requerida',
        confirmLabel: 'Aceptar',
        cancelLabel: 'Cancelar',
        placeholder: '',
        defaultValue: '',
        tone: 'info',
    },
};

const TONE_STYLES = {
    info: {
        icon: Info,
        iconClass: 'text-[#136191]',
        iconWrapClass: 'border-blue-200 bg-blue-50',
        confirmClass: 'bg-[#1A1A1A] text-white hover:bg-[#F39200]',
    },
    success: {
        icon: CheckCircle2,
        iconClass: 'text-emerald-600',
        iconWrapClass: 'border-emerald-200 bg-emerald-50',
        confirmClass: 'bg-emerald-600 text-white hover:bg-emerald-500',
    },
    warning: {
        icon: AlertTriangle,
        iconClass: 'text-[#F39200]',
        iconWrapClass: 'border-orange-200 bg-orange-50',
        confirmClass: 'bg-[#1A1A1A] text-white hover:bg-[#F39200]',
    },
    danger: {
        icon: AlertTriangle,
        iconClass: 'text-red-600',
        iconWrapClass: 'border-red-200 bg-red-50',
        confirmClass: 'bg-red-600 text-white hover:bg-red-500',
    },
    input: {
        icon: PencilLine,
        iconClass: 'text-[#136191]',
        iconWrapClass: 'border-blue-200 bg-blue-50',
        confirmClass: 'bg-[#1A1A1A] text-white hover:bg-[#F39200]',
    },
};

const resolveDialogConfig = (dialog) => {
    const defaults = DEFAULTS[dialog.type] || DEFAULTS.alert;
    const toneKey = dialog.tone || defaults.tone;
    return {
        ...defaults,
        ...dialog,
        tone: toneKey,
    };
};

export const AppDialogProvider = ({ children }) => {
    const queueRef = useRef([]);
    const resolverRef = useRef(null);
    const [activeDialog, setActiveDialog] = useState(null);
    const [promptValue, setPromptValue] = useState('');
    const [promptError, setPromptError] = useState('');

    const openDialog = useCallback((dialog) => new Promise((resolve) => {
        const nextDialog = { ...dialog, key: `${dialog.type}-${Date.now()}-${Math.random()}` };
        queueRef.current.push({ dialog: nextDialog, resolve });
        if (!activeDialog) {
            const next = queueRef.current.shift();
            resolverRef.current = next.resolve;
            setActiveDialog(next.dialog);
        }
    }), [activeDialog]);

    const closeDialog = (result) => {
        resolverRef.current?.(result);
        resolverRef.current = null;
        setActiveDialog(null);
        setPromptValue('');
        setPromptError('');
    };

    useEffect(() => {
        if (!activeDialog && queueRef.current.length > 0) {
            const next = queueRef.current.shift();
            resolverRef.current = next.resolve;
            setActiveDialog(next.dialog);
        }
    }, [activeDialog]);

    useEffect(() => {
        registerAppDialogHandler({
            alert: (options) => openDialog({ ...options, type: 'alert' }),
            confirm: (options) => openDialog({ ...options, type: 'confirm' }),
            prompt: (options) => openDialog({ ...options, type: 'prompt' }),
        });

        const nativeAlert = window.alert;
        window.alert = (message) => {
            void openDialog({ type: 'alert', message: String(message ?? '') });
        };

        return () => {
            unregisterAppDialogHandler();
            window.alert = nativeAlert;
        };
    }, [openDialog]);

    useEffect(() => {
        if (activeDialog?.type === 'prompt') {
            setTimeout(() => {
                setPromptValue(activeDialog.defaultValue || '');
                setPromptError('');
            }, 0);
        }
    }, [activeDialog]);

    const contextValue = useMemo(() => ({
        alert: appAlert,
        confirm: appConfirm,
        prompt: appPrompt,
    }), []);

    const dialog = activeDialog ? resolveDialogConfig(activeDialog) : null;
    const tone = dialog ? (TONE_STYLES[dialog.tone] || TONE_STYLES.info) : TONE_STYLES.info;
    const Icon = dialog?.type === 'prompt' ? MessageSquareQuote : tone.icon;

    const handleConfirm = () => {
        if (!dialog) return;
        if (dialog.type === 'prompt') {
            const value = promptValue.trim();
            if (!value) {
                setPromptError(dialog.requiredMessage || 'Este campo es obligatorio.');
                return;
            }
            closeDialog(value);
            return;
        }
        closeDialog(dialog.type === 'confirm' ? true : true);
    };

    const handleCancel = () => {
        if (!dialog) return;
        if (dialog.type === 'alert') {
            closeDialog(true);
            return;
        }
        closeDialog(dialog.type === 'prompt' ? null : false);
    };

    return (
        <AppDialogContext.Provider value={contextValue}>
            {children}
            <AnimatePresence>
                {dialog ? (
                    <motion.div
                        className="fixed inset-0 z-[140] flex items-center justify-center bg-black/45 backdrop-blur-sm p-4"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                    >
                        <motion.div
                            initial={{ opacity: 0, scale: 0.96, y: 16 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.98, y: 10 }}
                            transition={{ duration: 0.18 }}
                            className="w-full max-w-[520px] rounded-[2rem] border border-zinc-200 bg-[#F5F6F8] shadow-[0_30px_60px_rgba(0,0,0,0.18)] overflow-hidden"
                        >
                            <div className="flex items-start justify-between gap-4 border-b border-zinc-200 bg-white px-6 py-5">
                                <div className="flex items-start gap-4 min-w-0">
                                    <div className={`w-11 h-11 rounded-2xl border flex items-center justify-center shrink-0 ${tone.iconWrapClass}`}>
                                        <Icon className={`w-5 h-5 ${tone.iconClass}`} />
                                    </div>
                                    <div className="min-w-0">
                                        <div className="text-[12px] font-black uppercase tracking-[0.18em] text-zinc-900">
                                            {dialog.title}
                                        </div>
                                        {dialog.subtitle ? (
                                            <div className="mt-1 text-[11px] font-medium text-zinc-500">
                                                {dialog.subtitle}
                                            </div>
                                        ) : null}
                                    </div>
                                </div>
                                <button
                                    type="button"
                                    onClick={handleCancel}
                                    className="w-9 h-9 rounded-xl border border-zinc-200 bg-white flex items-center justify-center text-zinc-500 hover:text-zinc-900 hover:border-zinc-300 transition-all"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                            </div>

                            <div className="px-6 py-5 space-y-4">
                                <div className="text-[13px] leading-relaxed text-zinc-700 whitespace-pre-line">
                                    {dialog.message}
                                </div>

                                {dialog.type === 'prompt' ? (
                                    <div className="space-y-2">
                                        {dialog.label ? (
                                            <div className="text-[10px] font-black uppercase tracking-[0.16em] text-zinc-500">
                                                {dialog.label}
                                            </div>
                                        ) : null}
                                        <input
                                            autoFocus
                                            value={promptValue}
                                            onChange={(event) => {
                                                setPromptValue(event.target.value);
                                                if (promptError) setPromptError('');
                                            }}
                                            onKeyDown={(event) => {
                                                if (event.key === 'Enter') handleConfirm();
                                                if (event.key === 'Escape') handleCancel();
                                            }}
                                            placeholder={dialog.placeholder}
                                            className="w-full h-12 rounded-[1.1rem] border border-zinc-200 bg-white px-4 text-[13px] font-semibold text-zinc-800 outline-none focus:border-[#F39200]"
                                        />
                                        {promptError ? (
                                            <div className="text-[11px] font-bold text-red-600">{promptError}</div>
                                        ) : null}
                                    </div>
                                ) : null}
                            </div>

                            <div className="flex items-center justify-end gap-3 border-t border-zinc-200 bg-white px-6 py-5">
                                {dialog.type !== 'alert' ? (
                                    <button
                                        type="button"
                                        onClick={handleCancel}
                                        className="h-11 px-5 rounded-xl border border-zinc-200 bg-white text-[10px] font-black uppercase tracking-[0.16em] text-zinc-600 hover:border-zinc-300 hover:text-zinc-900 transition-all"
                                    >
                                        {dialog.cancelLabel}
                                    </button>
                                ) : null}
                                <LiquidButton
                                    onClick={handleConfirm}
                                    className={`!h-11 !px-5 rounded-xl text-[10px] tracking-[0.16em] ${tone.confirmClass}`}
                                >
                                    {dialog.confirmLabel}
                                </LiquidButton>
                            </div>
                        </motion.div>
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </AppDialogContext.Provider>
    );
};

export function useAppDialog() {
    return useContext(AppDialogContext);
}

